	@Test
	void writtenCookiesCarrySameSiteLaxInSetCookieHeader() {
		TransformationServlet servlet = mock(TransformationServlet.class);
		when(servlet.getCookieNames()).thenReturn(new String[] { "query", "queryLn", "infer", "query-timeout" });

		CookieHandler cookieHandler = new CookieHandler(
				new TestServletConfig("cookie-test", new MockServletContext(),
						java.util.Map.of("cookie-max-age", "60")),
				servlet);

		WorkbenchRequest request = mock(WorkbenchRequest.class);
		when(request.isParameterPresent("query")).thenReturn(true);
		when(request.isParameterPresent("queryLn")).thenReturn(true);
		when(request.isParameterPresent("infer")).thenReturn(true);
		when(request.isParameterPresent("query-timeout")).thenReturn(true);
		when(request.getParameter("query")).thenReturn("select * where { ?s ?p ?o }");
		when(request.getParameter("queryLn")).thenReturn("SPARQL");
		when(request.getParameter("infer")).thenReturn("true");
		when(request.getParameter("query-timeout")).thenReturn("0");
		when(request.getContextPath()).thenReturn("/workbench");
		when(request.getCookies()).thenReturn(null);

		CapturingCookieResponse response = new CapturingCookieResponse();
		cookieHandler.updateCookies(request, response);
		cookieHandler.addCookie(request, response, "ref", "hash");
		cookieHandler.addTotalResultCountCookie(request, response, 3);

		Collection<String> setCookieHeaders = response.getHeaders("Set-Cookie");
		assertThat(setCookieHeaders).extracting(header -> header.substring(0, header.indexOf('=')))
				.containsExactly("query", "queryLn", "infer", "query-timeout", "ref", "total_result_count");
		assertThat(setCookieHeaders).allSatisfy(header -> assertThat(header)
				.contains("; SameSite=Lax")
				.contains("; Path=/workbench")
				.contains("; Max-Age=60"));
	}

